// Pure numerical routines: RGBA storage, RGB processing, alpha preserved.
export const clamp=v=>Math.max(0,Math.min(255,Math.round(v)));
export function yuv(r,g,b){const y=.299*r+.587*g+.114*b;return [clamp(y),clamp(.492*(b-y)+128),clamp(.877*(r-y)+128)];}
export function channel(data,mode){const out=new Uint8ClampedArray(data.length);for(let i=0;i<data.length;i+=4){let v;if(mode==='original'){out.set(data.subarray(i,i+4),i);continue;}v='RGB'.includes(mode)?data[i+'RGB'.indexOf(mode)]:yuv(data[i],data[i+1],data[i+2])['YUV'.indexOf(mode)];out[i]=out[i+1]=out[i+2]=v;out[i+3]=data[i+3];}return out;}
export function histogram(data,mode='original'){const hs=Array.from({length:mode==='original'?3:1},()=>new Array(256).fill(0));for(let i=0;i<data.length;i+=4){if(mode==='original'){for(let c=0;c<3;c++)hs[c][data[i+c]]++;}else{const v='RGB'.includes(mode)?data[i+'RGB'.indexOf(mode)]:yuv(data[i],data[i+1],data[i+2])['YUV'.indexOf(mode)];hs[0][v]++;}}return hs;}
export function parseKernel(text){if(!text.trim())throw Error('矩陣不可為空。');let k;try{if(text.trim().startsWith('['))k=JSON.parse(text);else k=text.trim().split(/\n|;/).map(r=>r.trim().split(/[\s,]+/).map(Number));}catch{throw Error('矩陣格式錯誤，請使用每列一行或 JSON 二維陣列。');}if(!Array.isArray(k)||!k.length||k.length>15||k.length%2!==1||!k.every(r=>Array.isArray(r)&&r.length===k.length))throw Error('請輸入 1–15 階的奇數方陣，例如 3×3 或 5×5。');if(!k.every(r=>r.every(v=>typeof v==='number'&&Number.isFinite(v)&&Math.abs(v)<=1e6)))throw Error('權重必須為有限數值，絕對值不得超過 1,000,000。');return k;}
export function prepareKernel(k,normalize){const sum=k.flat().reduce((a,b)=>a+b,0);if(normalize&&Math.abs(sum)<1e-12)throw Error('矩陣總和為零，無法正規化；請取消正規化。');if(normalize&&Math.abs(sum)<1e-6)throw Error('矩陣總和過小，請調整權重或取消正規化。');return k.map(r=>r.map(v=>normalize?v/sum:v));}
export function convolve(data,width,height,k,{normalize=false,bias=0,border='reflect'}={}){k=prepareKernel(k,normalize);if(!Number.isFinite(bias)||Math.abs(bias)>255)throw Error('偏移量必須介於 -255 與 255。');const out=new Uint8ClampedArray(data.length),radius=(k.length-1)/2;function ix(v,n){if(border==='replicate')return Math.max(0,Math.min(n-1,v));if(n===1)return 0;while(v<0||v>=n){if(v<0)v=-v;if(v>=n)v=2*n-2-v;}return v;}
 for(let y=0;y<height;y++)for(let x=0;x<width;x++){const p=(y*width+x)*4;for(let c=0;c<3;c++){let val=bias;for(let ky=0;ky<k.length;ky++)for(let kx=0;kx<k.length;kx++){const sy=ix(y+radius-ky,height),sx=ix(x+radius-kx,width);val+=data[(sy*width+sx)*4+c]*k[ky][kx];}out[p+c]=clamp(val);}out[p+3]=data[p+3];}return out;}
export function quality(a,b){if(a.length!==b.length||!a.length||a.length%4)throw Error('比較影像尺寸必須相同且不為空。');let s=0;for(let i=0;i<a.length;i+=4)for(let c=0;c<3;c++)s+=(a[i+c]-b[i+c])**2;const mse=s/(a.length/4*3);return {mse,psnr:mse===0?Infinity:10*Math.log10(255**2/mse)};}

